function unitName(u){return (u.hero?generals[u.type].name:troop[u.type].name)+' Lv.'+s.loadout[u.type]}
function getGeneralAvailability(){const counts=Object.fromEntries(Object.keys(troop).map(t=>[t,s.units.filter(u=>!u.hero&&u.hp>0&&u.type===t).length]));return {counts,max:Math.max(...Object.values(counts)),alive:s.units.find(u=>u.hero&&u.hp>0),afford:s.gold>=220&&s.wood>=160}}
function syncCommands(){const a=getGeneralAvailability();Object.keys(troop).forEach(type=>{const b=generalButtons[type],eligible=a.counts[type]>=3&&a.counts[type]===a.max,ready=run&&!paused&&!s.over&&!a.alive&&a.afford&&eligible;b.disabled=!ready;b.classList.toggle('ready',ready);b.querySelector('small').textContent=troop[type].name+' · '+a.counts[type]+'人'+(eligible?' · 优势':'');b.title=a.alive?'已有将领在阵':!eligible?'同类普通士兵至少3人，且在场人数最多':!a.afford?'需要220矿石、160木材':'召唤'+generals[type].name+' · 生命'+unitStats({type,hero:true}).hp+' 攻击'+unitStats({type,hero:true}).damage});$('#generalStatus').textContent=a.alive?a.alive.hero&&unitName(a.alive)+' 在阵 · 同时仅一位将领':'220矿 / 160木 · 同类≥3且最多';$('#clearRallyBtn').disabled=!s.rally||!run||paused||s.over}
function makeUnit(type,hero=false){const cfg=unitStats({type,hero}),u={type,hero,x:gate.x+rnd(-18,18),y:gate.y+rnd(-14,14),hp:cfg.hp,max:cfg.hp,cd:0,face:1,phase:rnd(0,6.28),moving:false,attack:0,hit:0};s.units.push(u);if(s.rally)assignFormation();return u}
function summonGeneral(type){if(!generals[type]||!run||paused||s.over)return false;const a=getGeneralAvailability();if(a.alive||!a.afford||a.counts[type]<3||a.counts[type]!==a.max)return false;s.gold-=220;s.wood-=160;const u=makeUnit(type,true);text(u.x,u.y-75,generals[type].name+' · 应召出阵',generals[type].color);burst(u.x,u.y,'#e4bd65',26);s.fx.push({kind:'impact',x:u.x,y:u.y,life:1,max:1,color:'#e4bd65'});beep(660,.18);syncCommands();return true}
function rallyGround(px,py){if(px<35||px>1245||py<110||py>575||zones.some(z=>px>=z.x&&px<=z.x+z.w&&py>=z.y&&py<=z.y+z.h))return false;switch(activeMap.id){case'mountain':return !(px<405&&py>290);case'island':return !(px>860&&py>230);case'forest':return !(px<475&&py<390);case'volcano':return !(px>835&&py<380);case'desert':return !(px>440&&px<930&&py>385);default:return true}}
function assignFormation(){if(!s.rally)return;const live=s.units.filter(u=>u.hp>0),cols=Math.ceil(Math.sqrt(live.length));live.forEach((u,i)=>{const px=s.rally.x+(i%cols-(cols-1)/2)*28,py=s.rally.y+(Math.floor(i/cols)-(Math.ceil(live.length/cols)-1)/2)*25;u.rallyArrived=false;u.rally=rallyGround(px,py)?{x:px,y:py}:{...s.rally}})}
function issueRally(px,py){if(!run||paused||s.over||!rallyGround(px,py)||hoveredAlly()||hoveredEnemy())return false;s.rally={x:px,y:py};assignFormation();text(px,py-44,s.units.some(u=>u.hp>0)?'全军集合':'集结点已设定','#e5f3c4');s.fx.push({kind:'impact',x:px,y:py,life:.8,max:.8,color:'#a1c986'});beep(500,.07);syncCommands();return true}
function clearRally(){if(!run||paused||s.over)return;s.rally=null;s.units.forEach(u=>u.rally=null);ui.tip.textContent='已取消集合 · 全军自由迎敌';syncCommands()}
function healAlly(u,dt){if(u.hp<=0||u.hp>=u.max)return;const amount=Math.min(u.max-u.hp,(12+u.max*.025)*workRate('heal')*dt);u.hp+=amount;u.healAmount=(u.healAmount||0)+amount;if(s.healCd<=0){text(u.x,u.y-(u.hero?82:62),'+'+Math.max(1,Math.round(u.healAmount)),'#c1f2a2');u.healAmount=0;s.fx.push({kind:'heal',x:u.x,y:u.y-18,life:.6,max:.6,color:'#b3efa0'});s.healCd=.5}}
function workRate(kind){return Meta.rate(s.loadout,kind||'build')}
function blueprintFor(type){const t=troop[type];return t?{name:t.buildName,kind:'troop',gold:t.buildGold,wood:t.buildWood,time:3,size:124,color:t.roof}:Facility.blueprints[type]}
function typeAvailability(type){const b=blueprintFor(type);if(!b)return '未知建筑';if(b.kind==='troop'&&!s.unlocks.freeCamps)return '通过第一章后解锁自由建营';if(b.kind==='machine'&&!s.unlocks.machines)return '通过第二章后解锁采集机关';if(b.kind==='tower'&&s.loadout.wall<b.wall)return '需要城墙 Lv.'+b.wall;if(b.kind==='troop'&&zones.filter(z=>z.kind==='troop').length>=12)return '最多十二座兵营';if(b.kind==='tower'&&zones.filter(z=>z.type===type).length>=2)return '同类城防最多两座';if(s.gold<b.gold||s.wood<b.wood)return '矿石或木材不足';return ''}
function renderField(){if(!s)return;const tab=s.fieldTab;document.querySelectorAll('[data-field-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.fieldTab===tab)));$('.general-options').classList.toggle('hidden',tab!=='general');$('#fieldOptions').classList.toggle('hidden',tab==='general');$('.command-caption>b').textContent={general:'点将台',camp:'营建',tower:'城防',machine:'采集机关'}[tab];
 let types=tab==='camp'?Object.keys(troop):tab==='tower'?['arrowTower','cannon']:tab==='machine'?['oreMachine','woodMachine']:[];
 if(tab==='camp'&&!s.unlocks.freeCamps){$('#fieldOptions').innerHTML='<div class="field-lock">通过第一章后解锁自由选址与合营 · 当前悬停城内地基建营</div>';return}
 if(tab==='machine'&&!s.unlocks.machines){$('#fieldOptions').innerHTML='<div class="field-lock">通过第二章后解锁 · 局内制造，局外金币升级效率</div>';return}
 $('#fieldOptions').innerHTML=types.map(type=>{const b=blueprintFor(type),reason=typeAvailability(type);return '<button data-build="'+type+'" '+(reason?'disabled':'')+' title="'+(reason||'选择后点击有效位置安放')+'">'+b.name+'<small>'+b.gold+'矿 '+b.wood+'木</small></button>'}).join('')+(tab==='camp'?'<button id="mergeCampsBtn">合营<small>同类同阶 → 高一阶</small></button>':'')+(types.length?'<button id="cancelBuildBtn">收起工具<small>右键 / Esc</small></button>':'');
 if(tab==='camp')$('#mergeCampsBtn').onclick=()=>{if(!run||paused||!s.unlocks.freeCamps)return;s.placement=null;s.mergeMode=true;s.mergeSource=null;syncField()};if(types.length)$('#cancelBuildBtn').onclick=cancelTool;syncField();
}
$('.field-tabs').onclick=e=>{const b=e.target.closest('[data-field-tab]');if(b){s.fieldTab=b.dataset.fieldTab;renderField()}};
$('#fieldOptions').onclick=e=>{const b=e.target.closest('[data-build]');if(b&&!b.disabled)beginBuild(b.dataset.build)};
function syncField(){if(!s)return;document.querySelectorAll('[data-build]').forEach(b=>{const reason=typeAvailability(b.dataset.build);b.disabled=!!reason||!run||paused||s.over;b.title=reason||'点击空地安放，悬停继续建造';b.classList.toggle('selected',s.placement?.type===b.dataset.build)});if(s.fieldTab==='camp')$('#mergeCampsBtn')?.classList.toggle('selected',s.mergeMode);if(s.fieldTab!=='general')$('#generalStatus').textContent=s.fieldTab==='camp'?'兵营最多四阶 · 两座同类同阶合为一座':s.fieldTab==='tower'?'城墙3级解锁弓箭塔 · 6级解锁炮塔':'机器放在对应资源点 · 建成后自动工作';$('#commandHelp').textContent=s.placement?'点击有效位置安放 · 悬停完成营建 · 右键取消':s.mergeMode?'先点一座兵营，再点同类同阶兵营合并':'悬停己方治疗 · 点击空地集合 · 局外金币升级'}
function cancelTool(){if(!s)return;s.placement=null;s.mergeMode=false;s.mergeSource=null;syncField()}
function beginBuild(type){if(!run||paused||s.over)return false;const reason=typeAvailability(type);if(reason){ui.tip.textContent=reason;return false}s.placement={type};s.mergeMode=false;s.mergeSource=null;syncField();return true}
function placementPlan(type,px,py){
 const b=blueprintFor(type);if(!b)return {ok:false,reason:'未知建筑',cx:px,cy:py};let cx=px,cy=py,resourceId=null;
 if(b.kind==='machine'){const resource=zones.find(z=>z.kind===b.resource&&px>=z.x&&px<=z.x+z.w&&py>=z.y&&py<=z.y+z.h);if(!resource)return {ok:false,reason:'请选择'+(b.resource==='gold'?'矿区':'树林'),cx,cy};resourceId=resource.id;cx=Math.max(60,Math.min(1220,resource.x+resource.w/2));cy=Math.max(150,Math.min(565,resource.y+resource.h*.72));if(zones.some(z=>z.kind==='machine'&&z.resourceId===resourceId))return {ok:false,reason:'该资源点已有机关',cx,cy}}
 else{if(!rallyGround(cx,cy)||![-1,1].every(dx=>[-1,1].every(dy=>rallyGround(cx+dx*43,cy+dy*25))))return {ok:false,reason:'请选择开阔陆地',cx,cy};if(Math.hypot(cx-gate.x,cy-gate.y)<70||spawns.some(p=>Math.hypot(cx-p[0],cy-p[1])<90))return {ok:false,reason:'避开城门和敌军入口',cx,cy}}
 if(zones.some(z=>!['gold','wood'].includes(z.kind)&&Math.abs(cx-(z.x+z.w/2))<86&&Math.abs(cy-(z.y+z.h/2))<62))return {ok:false,reason:'建筑之间需要留出通道',cx,cy};
 return {ok:true,cx,cy,resourceId};
}
function tryPlace(type,px,py){if(!run||paused||s.over||typeAvailability(type))return false;const plan=placementPlan(type,px,py),b=blueprintFor(type);if(!plan.ok){text(px,py-25,plan.reason,'#df9b6c');return false}s.gold-=b.gold;s.wood-=b.wood;const z={id:'structure-'+(++s.nextStructure),kind:b.kind,type,x:plan.cx-48,y:plan.cy-32,w:96,h:64,name:b.name,tier:1,built:false,paid:true,resourceId:plan.resourceId,cd:0,production:0};zones.push(z);s.progress[z.id]=0;cancelTool();text(plan.cx,plan.cy-40,'材料已投入 · 悬停营建','#f4df9a');beep(360,.06);renderField();return z}
function mergePick(px,py){const z=[...zones].reverse().find(z=>z.kind==='troop'&&z.built&&px>=z.x&&px<=z.x+z.w&&py>=z.y&&py<=z.y+z.h);if(!z){ui.tip.textContent='请选择已建成的兵营';return false}if(!s.mergeSource){s.mergeSource=z.id;text(px,py-35,'已选 '+troop[z.type].buildName+' '+z.tier+'阶','#f4df9a');return false}const source=zones.find(a=>a.id===s.mergeSource);if(source===z){s.mergeSource=null;return false}return mergeCamps(source,z)}
function mergeCamps(a,b){if(!run||paused||s.over)return false;const reason=Facility.mergeReason(a,b,s.unlocks.freeCamps);if(reason){ui.tip.textContent=reason;return false}zones.splice(zones.indexOf(a),1);delete s.progress[a.id];b.tier++;s.progress[b.id]=0;s.mergeSource=null;s.mergeMode=false;text(b.x+b.w/2,b.y-30,troop[b.type].buildName+'升至 '+b.tier+'阶','#e8c471');burst(b.x+b.w/2,b.y+b.h/2,'#e8c471',25);beep(760,.15);renderField();return true}
function clickBattle(px,py){if(!run||paused||s.over)return false;if(s.placement)return tryPlace(s.placement.type,px,py);if(s.mergeMode)return mergePick(px,py);return issueRally(px,py)}
function updateFacilities(dt){for(const z of zones){if(!z.built)continue;z.fire=Math.max(0,(z.fire||0)-dt);const cx=z.x+z.w/2,cy=z.y+z.h/2;if(z.kind==='machine'){z.production=(z.production||0)+Meta.machineRate(s.loadout,z.type)*dt;const amount=Math.floor(z.production);if(amount>0){z.production-=amount;s[z.type==='oreMachine'?'gold':'wood']+=amount;z.fxCd=(z.fxCd||0)-dt;if(z.fxCd<=0){burst(cx,cy-10,z.type==='oreMachine'?'#dec46b':'#94b76f',2);z.fxCd=.7}}}else if(z.kind==='tower'){z.cd=(z.cd||0)-dt;if(z.cd>0)continue;const cfg=Facility.towerStats(z.type,s.loadout.wall);let target=null,near=cfg.range;s.enemies.forEach(e=>{const d=Math.hypot(e.x-cx,e.y-cy);if(e.hp>0&&d<near){near=d;target=e}});if(!target)continue;z.cd=cfg.interval;z.fire=.24;target.hp-=cfg.damage;target.flash=1;target.hit=.2;if(cfg.splash)s.enemies.forEach(e=>{if(e!==target&&e.hp>0&&dist(e,target)<cfg.splash){e.hp-=cfg.damage*.6;e.flash=1}});const life=.28;s.fx.push({kind:z.type==='cannon'?'shell':'arrow',x:cx,y:cy-42,vx:(target.x-cx)/life,vy:(target.y-18-(cy-42))/life,life,max:life,color:z.type==='cannon'?'#e4a261':'#e1d2a4'});if(z.type==='cannon'){s.fx.push({kind:'impact',x:target.x,y:target.y,life:.5,max:.5,color:'#e9b568'});burst(target.x,target.y,'#e9b568',10)}}}}
function action(dt){
 s.healCd=Math.max(0,s.healCd-dt);if(s.placement||s.mergeMode){ui.tip.textContent=s.mergeMode?(s.mergeSource?'再点击同类同阶兵营合并 · 右键取消':'先点击一座已建成兵营 · 右键取消'):'选择位置安放'+blueprintFor(s.placement.type).name+' · 右键取消';return}
 const ally=hoveredAlly(),a=ally?null:zone();zones.forEach(z=>{if(z!==a&&(z.kind==='gold'||z.kind==='wood'||z.built))s.progress[z.id]=Math.max(0,(s.progress[z.id]||0)-dt*.6)});
 if(ally){ui.tip.textContent=unitName(ally)+(ally.hp<ally.max?' · 正在治疗 '+Math.ceil(ally.hp)+'/'+ally.max:' · 生命已满');healAlly(ally,dt);return}
 if(!a){ui.tip.textContent=hoveredEnemy()?'瞄准敌军 · 光标协助攻击':s.rally?'集结点已设定 · 悬停己方治疗 / 点击空地重新集合':'悬停采集、招兵、治疗 · 点击空地集合';return}
 if(a.kind==='gold'||a.kind==='wood'){s.progress[a.id]+=dt*workRate(a.kind==='gold'?'mine':'wood');ui.tip.textContent=a.name+' · '+a.hint;if(s.progress[a.id]>=a.rate){s.progress[a.id]-=a.rate;s[a.kind==='gold'?'gold':'wood']+=3;burst(p.x,p.y,a.kind==='gold'?'#f6c445':'#77a64b',4)}return}
 const cfg=blueprintFor(a.type);
 if(!a.built){s.progress[a.id]+=dt*workRate('build');ui.tip.textContent='建造'+cfg.name+' · '+(a.paid?'材料已投入':cfg.gold+'矿 '+cfg.wood+'木');if(s.progress[a.id]>=cfg.time){s.progress[a.id]=0;construct(a.type,a)}}
 else if(a.kind==='troop'){s.progress[a.id]+=dt*workRate('recruit')*Facility.campRate(a.tier);ui.tip.textContent=cfg.name+' '+a.tier+'阶 · 招募'+troop[a.type].name+' '+troop[a.type].gold+'矿 '+troop[a.type].wood+'木';if(s.progress[a.id]>=troop[a.type].rate){s.progress[a.id]=0;recruit(a.type,a)}}
 else ui.tip.textContent=cfg.name+(a.kind==='machine'?' · 自动产出 '+Meta.machineRate(s.loadout,a.type).toFixed(2)+'/秒':' · 自动防卫');
}
function construct(type,z=zones.find(z=>z.kind==='troop'&&z.type===type&&!z.built)){if(!z||z.built)return false;const cfg=blueprintFor(type);if(!z.paid){if(s.gold<cfg.gold||s.wood<cfg.wood){text(p.x,p.y-30,'建造资源不足','#e25c52');return false}s.gold-=cfg.gold;s.wood-=cfg.wood}z.built=true;z.tier||=1;z.cd=0;z.production=0;if(z.kind==='troop')s.buildings[type]=true;text(z.x+z.w/2,z.y-30,cfg.name+'建成！','#f6d66d');burst(z.x+z.w/2,z.y+z.h/2,'#d6c69a',15);beep(440,.06);renderField();return true}
function recruit(type,source){const cfg=troop[type];if(s.gold<cfg.gold||s.wood<cfg.wood){text(p.x,p.y-28,'招募资源不足','#e25c52');return false}s.gold-=cfg.gold;s.wood-=cfg.wood;const u=makeUnit(type);if(s.unlocks.freeCamps&&source){const cx=source.x+source.w/2,cy=source.y+source.h/2,dx=640-cx,dy=300-cy,n=Math.hypot(dx,dy);u.x=cx+(n?dx/n:0)*65;u.y=cy+(n?dy/n:-1)*65}text(u.x,u.y-35,cfg.name+'出征','#f6d66d');beep(type==='mage'?720:type==='archer'?560:360,.06);return true}
function spawn(){const pt=spawns[Math.floor(Math.random()*spawns.length)],brute=Math.random()<s.stage.bruteChance+s.wave*.025,hp=(brute?115*1.25:46*1.3)*(1+s.wave*.12)*s.stage.health;s.enemies.push({type:brute?'brute':'raider',x:pt[0]+rnd(-13,13),y:pt[1]+rnd(-9,9),hp,max:hp,speed:((brute?23:36)+s.wave)*s.stage.speed,cd:0,flash:0,focus:0,phase:rnd(0,6.28),moving:true,attack:0,hit:0,face:-1})}
function step(dt){s.time+=dt;s.raidAlert=Math.max(0,s.raidAlert-dt);s.shake=Math.max(0,s.shake-dt*7);s.cursorCd=Math.max(0,s.cursorCd-dt);if(s.between>0){s.between-=dt;if(s.between<=0){s.waveTime=0;s.next=.1;beep(180,.16)}}else{let duration=s.stage.duration,count=4+s.wave*2+s.stage.extraEnemies;s.waveTime+=dt;if(s.waveTime<duration&&s.waveTime>=s.next){spawn();s.next+=duration/count*rnd(.75,1.05)}if(s.beastsSent<s.stage.tier&&s.waveTime>=6+s.beastsSent*5)spawnAnimal();if(s.waveTime>=duration&&!s.enemies.length){if(s.wave>=s.stage.waves){win();return}s.wave++;s.beastsSent=0;s.between=s.stage.rest;s.gold+=20;s.wood+=16;text(640,285,'波次守住！ +20矿 +16木','#f6d66d');beep(760,.18)}}action(dt);units(dt);updateFacilities(dt);enemies(dt);effects(dt);sync()}
function beginEnemyAttack(e,target=null){e.vx=0;e.vy=0;e.attackSpan=motion.duration(e);e.attack=e.attackSpan;e.strike={target,delay:e.attackSpan*.5};e.cd=target?1.1:1.25;e.face=(target?.x??gate.x)>=e.x?1:-1}
function resolveEnemyStrike(e,target){if(e.hp<=0)return;const dmg=(e.type==='brute'?(target?14:13):(target?7:6))*s.stage.damage*1.18;if(target){if(target.hp<=0||!s.units.includes(target)||dist(e,target)>54)return;target.hp-=dmg;target.hit=.22;s.shake=.2;beep(90,.03)}else if(dist(e,gate)<48){const hit=Math.round(dmg);s.hp-=hit;s.shake=.7;text(gate.x,gate.y-45,'-'+hit,'#e85b52');beep(70,.08)}}
function enemies(dt){
 for(let i=s.enemies.length-1;i>=0;i--){
  const e=s.enemies[i];if(e.hp<=0){defeatEnemy(e,i);continue}
  e.cd-=dt;e.flash=Math.max(0,e.flash-dt*5);e.attack=Math.max(0,e.attack-dt);e.hit=Math.max(0,e.hit-dt);e.moving=false;
  const focus=!hoveredAlly()&&Math.hypot(p.x-e.x,p.y-e.y)<enemyRadius(e);e.focus=clamp(e.focus+(focus?dt*2:-dt*3),0,1);
  if(focus&&s.cursorCd<=0){e.hp-=Meta.attackDamage(s.loadout);e.flash=1;e.hit=.2;s.cursorCd=Meta.attackInterval(s.loadout);s.fx.push({kind:'cursor',x:p.x,y:p.y,vx:(e.x-p.x)*5,vy:(e.y-p.y)*5,life:.2,max:.2,color:'#ffe36c'});burst(e.x,e.y-8,'#ffe36c',3);beep(980,.025,'sine')}
  if(e.hp<=0){defeatEnemy(e,i);continue}
  if(e.type==='beast'){chargeAnimal(e,dt);continue}
  if(e.strike){e.strike.delay-=dt;if(e.strike.delay<=0){const target=e.strike.target;e.strike=null;resolveEnemyStrike(e,target)}}
  if(e.attack>0)continue;
  let u=null,d=1e9;s.units.forEach(q=>{let n=dist(e,q);if(q.hp>0&&n<d){d=n;u=q}});
  if(u&&d<38){if(e.cd<=0)beginEnemyAttack(e,u)}
  else{const dx=gate.x-e.x,dy=gate.y-e.y,n=Math.hypot(dx,dy);if(n>32){const alpha=1-Math.exp(-dt*9);e.vx=(e.vx||0)+(dx/n*e.speed-(e.vx||0))*alpha;e.vy=(e.vy||0)+(dy/n*e.speed-(e.vy||0))*alpha;const speed=Math.hypot(e.vx,e.vy),moved=Math.min(n-32,speed*dt);if(speed>0){e.x+=e.vx/speed*moved;e.y+=e.vy/speed*moved}motion.walk(e,moved);e.moving=moved>.02;if(Math.abs(e.vx)>5)e.face=e.vx>0?1:-1}else if(e.cd<=0)beginEnemyAttack(e)}
 }if(s.hp<=0&&!s.over)lose()
}
function moveUnit(u,target,dt,cfg){const dx=target.x-u.x,dy=target.y-u.y,d=Math.hypot(dx,dy);if(d<=3){u.vx=0;u.vy=0;return}let sx=dx/d,sy=dy/d;s.units.forEach(v=>{if(v===u||v.hp<=0)return;let ox=u.x-v.x,oy=u.y-v.y,n=Math.hypot(ox,oy);if(n<25){if(n<.1){ox=Math.cos(u.phase)*.5;oy=Math.sin(u.phase)*.5;n=.5}const push=(25-n)/25*.7;sx+=ox/n*push;sy+=oy/n*push}});const sn=Math.hypot(sx,sy)||1,alpha=1-Math.exp(-dt*10);u.vx=(u.vx||0)+(sx/sn*cfg.speed-(u.vx||0))*alpha;u.vy=(u.vy||0)+(sy/sn*cfg.speed-(u.vy||0))*alpha;let mx=u.vx*dt,my=u.vy*dt,n=Math.hypot(mx,my);if(n>d){mx*=d/n;my*=d/n;n=d}u.x+=mx;u.y+=my;motion.walk(u,n);if(Math.abs(u.vx)>5)u.face=u.vx>=0?1:-1;u.moving=n>.02}
