 const color=u.hero?cfg.color:null;
 if(u.type==='archer'||u.type==='mage'){const life=u.type==='archer'?.32:.38,px=u.x+u.face*(u.hero?24:18),py=u.y-(u.hero?32:24);s.fx.push({kind:u.type==='archer'?'arrow':'magic',x:px,y:py,vx:(target.x-px)/life,vy:(target.y-18-py)/life,life,max:life,color:color||(u.type==='archer'?'#d7c59e':'#76547f')})}
 else{s.fx.push({kind:u.type==='spearman'?'thrust':'slash',x:target.x,y:target.y,life:.24,max:.24,color:color||(u.type==='spearman'?'#d9e0d4':'#b6372f'),angle:Math.atan2(target.y-u.y,target.x-u.x)});burst(target.x,target.y,color||'#a83b2f',5)}
