  u.displayHp=Math.max(u.hp,(u.displayHp??u.max)+(u.hp-(u.displayHp??u.max))*(1-Math.exp(-dt*8)));u.cd-=dt;u.attack=Math.max(0,u.attack-dt);u.hit=Math.max(0,u.hit-dt);u.moving=false;
